#!/usr/bin/env python3
"""Trilha FUNDAMENTOS do curso de Formação de Professores: 6 lições de 10 quadros (didática do ensino de inglês + TOEFL).
Texto autoral. Usa os mesmos tipos de quadro do player (can, text, cards, quiz, teach, toefl, wrap). Saída: data/formacao/fund/."""
import json,os
R=os.path.abspath(os.path.join(os.path.dirname(__file__),'..'));OUT=R+'/data/formacao/fund';os.makedirs(OUT,exist_ok=True)
TF=('Formato inspirado no TOEFL iBT','Confira o formato e a pontuação vigentes no site da ETS antes de usar em curso preparatório. As tarefas abaixo são práticas de preparação, não simulados oficiais.')
def can(goal,items,note=''):return dict(k='can',tag='OBJETIVO',title='O que você vai aprender',goal=goal,can=items,note=note,cefr='')
def text(tag,title,secs):return dict(k='text',tag=tag,title=title,sections=secs)
def cards(tag,title,items):return dict(k='cards',tag=tag,title=title,items=[dict(front=a,back=b,ex=[c] if c else []) for a,b,c in items],say=False)
def quiz(title,items):return dict(k='quiz',tag='VERIFIQUE',title=title,items=[dict(q=q,opts=o,ans=a,why=w) for q,o,a,w in items])
def teach(title,goal,steps,errors,adapt,ccq):return dict(k='teach',tag='NA PRÁTICA',title=title,goal=goal,steps=[dict(t=a,d=b) for a,b in steps],errors=errors,adapt=adapt,ccq=ccq)
def toefl(tasks):return dict(k='toefl',tag='TOEFL',title='Ponte para o TOEFL',tip=list(TF),tasks=tasks)
def wrap(micro,homework):return dict(k='wrap',tag='FECHAMENTO',title='Fechamento e tarefa',items=[],micro=micro,homework=homework)
def S(h,p='',ul=None):return dict(h=h,p=p,ul=ul or [])

L=[]
# ---------------------------------------------------------------- 1
L.append(('Planejar com o QECR (CEFR) e metas de desempenho','Níveis A1–C2, níveis “+”, descritores “eu consigo” e o lugar do TOEFL.',[
 can('Planejar aulas a partir do que o aluno consegue fazer, não do que o livro cobre.',['Ler um descritor do QECR e transformá-lo em objetivo de aula.','Explicar a diferença entre nível, meta de desempenho e certificação.','Situar o TOEFL na escala.'],'O QECR descreve o que a pessoa consegue fazer com a língua. Ele não é um currículo nem uma prova.'),
 text('CONCEITO','A escala em uma olhada',[S('Seis níveis, três faixas','O QECR agrupa a proficiência em usuário básico (A1, A2), independente (B1, B2) e proficiente (C1, C2).',['**A1**: frases cotidianas muito simples, em interação lenta.','**A2**: tarefas simples e rotineiras, trocas curtas.','**B1**: lida com a maioria das situações de viagem e trabalho, descreve experiências e planos.','**B2**: discute com espontaneidade, entende textos complexos sobre temas concretos e abstratos.','**C1**: usa a língua com fluidez e flexibilidade para fins sociais, acadêmicos e profissionais.','**C2**: entende praticamente tudo e se expressa com precisão e nuances.'])]),
 text('CONCEITO','Os níveis “+” e a mediação',[S('Volume Complementar (2020)','O Volume Complementar do QECR detalha subníveis (A2+, B1+, B2+), inclui o nível “Pré-A1” e acrescenta escalas de **mediação** (explicar, resumir, facilitar a comunicação) e de interação online. O professor ganha uma régua mais fina: dois alunos “B1” podem estar a meses de distância, e o plano precisa mostrar isso.'),S('Por que isso importa na sala','Planejar “do A1 ao C2” sem subníveis cria saltos grandes demais. Quebre a trilha em metas de 4 a 8 semanas.')]),
 cards('TERMOS','Cinco palavras para usar com precisão',[('Descritor “eu consigo”','Frase curta que diz o que o aluno faz com a língua em um nível.','“Consigo pedir comida e pagar a conta.”'),('Meta de desempenho','Resultado observável da aula, descrito com verbo de ação.','“Ao final, o aluno pede um café e esclarece o preço.”'),('Tarefa comunicativa','Atividade com propósito além da língua (resolver, decidir, descobrir).','Combinar horário de uma consulta.'),('Input compreensível','Língua um pouco acima do que o aluno domina, com apoio de contexto.','Diálogo com imagens e glossário.'),('Mediação','Ajudar outra pessoa a entender ou a se expressar.','Explicar um aviso a um colega.')]),
 quiz('Verifique seu entendimento',[('Qual frase é uma boa meta de desempenho para o A1?',['Estudar o presente simples.','Ao final, o aluno se apresenta e pergunta o nome do colega.','Memorizar 50 palavras.'],1,'Meta de desempenho descreve algo observável que o aluno faz.'),('O que o QECR é?',['Um currículo obrigatório.','Uma descrição do que o aluno consegue fazer em cada nível.','Uma prova internacional.'],1,'Ele descreve proficiência. Currículos e provas se alinham a ele, mas não são o QECR.'),('Qual nível indica o aluno “independente”?',['A2','B1–B2','C2'],1,'B1 e B2 formam a faixa de usuário independente.')]),
 text('MÉTODO','Planejamento reverso em 3 passos',[S('Do resultado para a atividade','1) Escolha o descritor do nível e da situação. 2) Defina o que você aceitará como evidência (uma fala, um texto, uma escolha correta). 3) Só então escolha as atividades e o vocabulário que levam até lá.',['**Evidência primeiro**: se não sabe como vai verificar, o objetivo está vago.','**Uma situação por aula**: pedir um café, perguntar um caminho, resolver um problema.','**Do geral ao específico**: comece por situações do dia a dia e vá afunilando (consulta médica, entrevista, apresentação).'])]),
 teach('Na prática: monte uma meta em 5 minutos','Escrever uma meta de desempenho e a evidência dela para um nível e uma situação à sua escolha.',[('Escolha','Selecione nível (por exemplo A2) e situação (por exemplo, marcar uma consulta).'),('Escreva','Use o molde: “Ao final, o aluno [verbo de ação] [o quê] em [situação].”'),('Evidência','Defina como saberá que funcionou: uma fala gravada de 20 segundos, por exemplo.'),('Teste','Peça a um colega que leia a meta e diga o que a aula vai ter.')],['Metas com verbos vagos (“conhecer”, “entender”) que não dão evidência.','Confundir o conteúdo da aula (“present perfect”) com o resultado (“contar o que já fez hoje”).'],'Para turmas mistas, escreva duas metas: uma mínima e uma de desafio.',['Que verbo mostra o que o aluno faz?','Como você saberia que ele conseguiu?']),
 text('ARMADILHAS','Erros comuns de planejamento',[S('Evite','',['Tratar o nível do livro como o nível do aluno: faça um diagnóstico.','Pular o nível “+”: o salto de B1 para B2 costuma exigir 2 a 3 metas intermediárias.','Planejar só gramática: o QECR fala de tarefas, e a gramática é meio, não fim.','Anunciar “certificação”: as metas da aula são de desempenho, não certificam nada.'])]),
 toefl([dict(type='cloze',name='Vocabulary in context',items=[dict(q='The teacher set a clear _____ for the lesson: students will ask for directions.',opts=['goal','weather','price'],ans=0,why='“Goal” (meta) combina com “set a clear … for the lesson”.'),dict(q='Learners at B2 can interact with a degree of _____ without much searching for words.',opts=['fluency','distance','recipe'],ans=0,why='“Fluency” é a espontaneidade de fala esperada em B2.')])]),
 wrap('Ensine em 60 segundos: explique a um colega a diferença entre A2 e B1 usando dois descritores “eu consigo”.','Escolha uma situação do dia a dia e escreva metas de desempenho para A1, A2 e B1 sobre ela.')]))
# ---------------------------------------------------------------- 2
L.append(('Ensinar vocabulário e expressões','Saber uma palavra tem camadas: sentido, forma, uso, combinações e pronúncia.',[
 can('Ensinar palavras e expressões de modo que o aluno as use, e não só as reconheça.',['Descrever o que significa “saber” uma palavra.','Escolher técnicas de apresentação e de prática.','Planejar revisão espaçada.'],'Uma palavra aprendida em uma aula só fica se for recuperada de novo depois.'),
 text('CONCEITO','O que é saber uma palavra',[S('Camadas de conhecimento','',['**Sentido**: o que significa e o que não significa.','**Forma**: ortografia, pronúncia, sílaba forte e plurais.','**Uso**: registro formal ou informal, e em que situação aparece.','**Combinações**: com quais palavras anda (make a decision, não do a decision).','**Produção**: consegue usá-la sem apoio.']),S('Consequência','Mostrar uma palavra e a tradução trabalha só a primeira camada. Planeje atividades que toquem as outras.')]),
 text('CONCEITO','Chunks: o inglês vem em blocos',[S('Aprender blocos, não palavras soltas','Falantes usam blocos prontos (“How much is it?”, “I’m thinking about…”). Ensinar o bloco dá fluência imediata e traz junto a gramática e a pronúncia do conjunto.',['Ensine **I’d like to…** antes de explicar o condicional.','Apresente verbo + preposição juntos: **apply for**, **look for**.','Agrupe por situação (restaurante, hotel) e não por ordem alfabética.'])]),
 cards('TÉCNICAS','Cinco jeitos de apresentar',[('Mostrar','Objeto, imagem ou gesto antes da tradução.','“campus”, “lecture hall” com foto.'),('Contextualizar','Frase com a palavra em uso, antes da definição.','“The library is open twenty-four hours.”'),('Contrastar','Colocar ao lado de uma palavra parecida.','look × see × watch'),('Definir simples','Dar definição em inglês simples ou tradução curta.','“Dean: the person in charge of a college department.”'),('Perguntas de checagem (CCQ)','Perguntas que testam o sentido sem pedir definição.','“Is a lecture a place or an event?”')]),
 quiz('Verifique seu entendimento',[('Qual pergunta é uma boa pergunta de checagem (CCQ) para “borrow”?',['Do you know what borrow means?','If I borrow your pen, do I keep it forever?','Can you translate borrow?'],1,'CCQ confere o sentido com um cenário, sem pedir definição.'),('Por que ensinar chunks?',['Porque são mais curtos.','Porque trazem fluência, gramática e pronúncia juntas.','Porque dispensam a revisão.'],1,'O bloco carrega o uso real da língua.'),('Quando a revisão funciona melhor?',['Tudo no mesmo dia.','Em intervalos crescentes (amanhã, em 3 dias, em uma semana).','Só antes da prova.'],1,'A recuperação espaçada fixa a memória por mais tempo.')]),
 text('MÉTODO','Prática em três degraus',[S('Do controle à liberdade','',['**Controlada**: completar, ligar, escolher. Foco na forma.','**Guiada**: responder com um molde de frase. Foco no uso.','**Livre**: falar de si ou resolver uma tarefa. Foco no sentido, e a palavra volta por conta do aluno.']),S('Revisão espaçada','Programe três retornos: no fim da aula, na aula seguinte e uma semana depois, sempre em contexto novo.')]),
 teach('Na prática: apresentar 4 palavras em 10 minutos','Apresentar e praticar quatro palavras de uma situação (por exemplo, “at the doctor”) de forma que o aluno as use em frases suas.',[('Mostrar (2 min)','Imagem ou mímica para cada palavra, sem tradução.'),('Dizer (2 min)','Repetição em coro e individual, marcando a sílaba forte.'),('Checar (2 min)','Duas perguntas CCQ por palavra.'),('Usar (4 min)','Cada aluno completa o molde “I have a ___” e depois faz uma pergunta ao colega.')],['Dar a tradução primeiro e deixar o aluno só repetir.','Ensinar 15 palavras de uma vez: o limite útil por aula é 5 a 8.'],'Para alunos iniciantes, comece sempre pelo concreto (objetos, ações). Para B2+, ensine colocações e registro.',['Quando você diria essa palavra?','Que outra palavra anda junto com ela?']),
 text('ARMADILHAS','Erros comuns',[S('Evite','',['Listas de vocabulário sem situação.','Falsos cognatos sem aviso: **actually** não é “atualmente”, **push** não é “puxar”, **pretend** não é “pretender”.','Corrigir só a ortografia e esquecer a pronúncia da sílaba forte.','Nunca revisitar o que foi ensinado.'])]),
 toefl([dict(type='cloze',name='Vocabulary in context',items=[dict(q='“Actually” in English means “in fact”, so it is a false _____ for Portuguese speakers.',opts=['friend','sister','map'],ans=0,why='“False friend” é o falso cognato.'),dict(q='The students will _____ the new words again next week to remember them.',opts=['review','weather','whisper'],ans=0,why='“Review” é revisar.')]),dict(type='repeat',name='Listen and Repeat',items=[dict(en='I would like to book a table.',pt='Eu gostaria de reservar uma mesa.'),dict(en='Could you tell me how much it costs?',pt='Você poderia me dizer quanto custa?')])]),
 wrap('Ensine em 60 segundos: apresente uma palavra nova usando uma imagem mental e uma pergunta de checagem.','Planeje 4 palavras de uma situação à sua escolha e escreva uma pergunta CCQ para cada.')]))
# ---------------------------------------------------------------- 3
L.append(('Ensinar gramática','Descoberta guiada, PPP e tarefas, e como corrigir sem desmotivar.',[
 can('Ensinar uma estrutura de modo que o aluno entenda a regra e a use em situações reais.',['Escolher entre apresentar a regra ou guiar a descoberta.','Montar uma aula em PPP e uma em tarefa.','Corrigir erros com técnicas diferentes.'],'Gramática é meio para comunicar. A pergunta de partida é: “o que o aluno precisa dizer?”.'),
 text('CONCEITO','Duas rotas: dedutiva e indutiva',[S('Dedutiva','O professor apresenta a regra e o aluno pratica. Rápida e útil com adultos que querem clareza.'),S('Indutiva (descoberta guiada)','O aluno observa exemplos, formula a regra e só então o professor confirma. Dura mais, mas a regra fica.',['**Passo 1**: dê 4 a 6 exemplos de uma estrutura em contexto.','**Passo 2**: pergunte “o que se repete? o que muda?”.','**Passo 3**: o aluno escreve a regra com as próprias palavras.','**Passo 4**: você confirma, ajusta e dá o nome técnico.'])]),
 text('MÉTODO','PPP e aula por tarefa',[S('PPP: apresentar, praticar, produzir','Eficiente para estruturas simples e para iniciantes: contexto e modelo, prática controlada, produção livre.'),S('Tarefa (TBL)','O aluno tenta cumprir uma tarefa (planejar uma festa), o professor observa as lacunas, trabalha a língua que faltou e a tarefa se repete melhorada.',['PPP dá segurança. Tarefa dá autonomia.','Mescle: PPP em A1–A2 e tarefas cada vez mais abertas em B1+.'])]),
 cards('FEEDBACK','Seis jeitos de corrigir',[('Reformular (recast)','Repetir certo, sem apontar o erro.','Aluno: “She go to school.” Você: “She goes to school.”'),('Elicitar','Parar antes do erro e deixar o aluno completar.','“She… ?”'),('Pista metalinguística','Dar uma pista sobre a regra.','“Terceira pessoa…”'),('Repetir o erro','Repetir o erro com entonação de pergunta.','“She go?”'),('Correção explícita','Dizer que está errado e dar a forma certa.','“Não: she goes.”'),('Adiar','Anotar o erro e tratar no fim da atividade.','Quadro de “erros do dia”.')]),
 quiz('Verifique seu entendimento',[('Qual rota pede que o aluno formule a regra antes do professor?',['Dedutiva','Indutiva (descoberta guiada)','Tradução'],1,'Na descoberta guiada o aluno chega à regra a partir dos exemplos.'),('Em uma atividade de fluência, qual correção é a mais adequada?',['Interromper em cada erro.','Anotar e corrigir depois.','Ignorar para sempre.'],1,'Adiar protege o fluxo da fala.'),('Quando o aluno diz “She go to school” e você diz “She goes to school”, é:',['Elicitação','Reformulação (recast)','Correção explícita'],1,'Você repete certo, sem apontar o erro.')]),
 text('MÉTODO','Forma, sentido e uso',[S('Três perguntas para qualquer estrutura','',['**Forma**: como se constrói? (sujeito + verbo + -s na 3ª pessoa)','**Sentido**: o que significa e o que não significa? (hábito, não ação neste instante)','**Uso**: quando e com quem se usa? (rotina, fatos, horários)']),S('Dica de planejamento','Antes da aula, responda às três perguntas em uma linha cada. Se não conseguir, a estrutura ainda não está clara para você, e muito menos para o aluno.')]),
 teach('Na prática: descoberta guiada em 12 minutos','Levar os alunos a formular a regra do -s da terceira pessoa a partir de exemplos.',[('Exemplos (3 min)','Escreva 6 frases sobre a rotina de alguém: “Ana works at nine.” “I work at ten.”'),('Observar (3 min)','Pergunte “o que se repete? o que muda?”.'),('Formular (3 min)','Em duplas, os alunos escrevem a regra com as próprias palavras.'),('Aplicar (3 min)','Cada aluno conta a rotina de um colega em 3 frases.')],['Dar regras longas sem exemplo.','Corrigir tudo ao mesmo tempo: escolha um foco por atividade.'],'Para turmas ansiosas, comece pela reformulação e deixe a correção explícita para a escrita.',['O que mudou entre as duas frases?','Em que situação usamos essa forma?']),
 text('ARMADILHAS','Erros típicos de brasileiros que você vai ouvir',[S('Fique atento','',['“I have 20 years” em vez de “I’m twenty” (idade com o verbo be).','Esquecer o **-s** da terceira pessoa.','“Can you to help me?” (modal não leva to).','Omitir o sujeito: “Is raining” em vez de “It’s raining”.','“Did you went?” (auxiliar e verbo no passado ao mesmo tempo).'])]),
 toefl([dict(type='build',name='Build a Sentence',items=[dict(words=['usually','she','at','works','nine'],answer='She usually works at nine.',pt='Ela costuma trabalhar às nove.'),dict(words=['you','did','where','go','yesterday'],answer='Where did you go yesterday?',pt='Aonde você foi ontem?')])]),
 wrap('Ensine em 60 segundos: explique a regra do -s da terceira pessoa com dois exemplos seus.','Escolha uma estrutura (por exemplo, o passado simples) e escreva 6 exemplos para uma aula de descoberta guiada.')]))
# ---------------------------------------------------------------- 4
L.append(('Ensinar listening e leitura','Subhabilidades, as três etapas da aula e os formatos do TOEFL.',[
 can('Planejar atividades de escuta e leitura que treinam estratégias, e não apenas verificam respostas.',['Distinguir ouvir pela ideia geral e pelo detalhe.','Montar a sequência pré, durante e pós.','Reconhecer os formatos de leitura e escuta do TOEFL.'],'Compreender é um processo ativo: o aluno usa o que já sabe para prever, e confere o que entendeu.'),
 text('CONCEITO','De cima para baixo e de baixo para cima',[S('Dois processos','',['**De cima para baixo**: usar o contexto e o conhecimento prévio para prever.','**De baixo para cima**: decodificar sons, palavras e frases.']),S('O que fazer','Alunos de nível baixo dependem do contexto (imagens, título). Trabalhe também os sons que atrapalham: linking (“want to” → “wanna”), formas fracas e finais de palavra.')]),
 text('MÉTODO','As três etapas da aula',[S('Pré','Ative o conhecimento e prepare o vocabulário-chave. Peça previsões.'),S('Durante','Duas passadas: a primeira pela ideia geral, a segunda por detalhes. Uma tarefa por escuta.'),S('Pós','Discuta o que entenderam, e só então volte ao texto para olhar a língua (expressões, estruturas, pronúncia).',['Nunca peça “entendeu?”: peça uma evidência (“onde está a resposta?”).'])]),
 cards('SUBHABILIDADES','Seis estratégias para treinar',[('Skimming','Ler rápido pela ideia geral.','Título, primeira frase de cada parágrafo.'),('Scanning','Buscar uma informação específica.','Um horário, um nome, um preço.'),('Inferir','Concluir o que não está dito.','“She looked at her watch again.” Está atrasada?'),('Vocabulário em contexto','Deduzir sentido pelo entorno.','Palavras vizinhas e exemplos.'),('Identificar o propósito','Por que o autor escreveu ou o falante falou?','Informar, pedir, convencer.'),('Resumir','Dizer o texto com poucas palavras.','Uma frase por parágrafo.')]),
 quiz('Verifique seu entendimento',[('Skimming serve para:',['Achar uma informação específica.','Entender a ideia geral rapidamente.','Corrigir a gramática.'],1,'Skimming é a leitura rápida pela ideia geral.'),('Qual tarefa combina com a primeira escuta?',['Escrever uma transcrição.','Dizer quem fala e onde estão.','Traduzir palavra por palavra.'],1,'A primeira escuta pede a ideia geral.'),('Na etapa pós, o ideal é:',['Encerrar na correção das respostas.','Voltar ao texto para olhar a língua em uso.','Passar outro texto sem discussão.'],1,'O pós aproveita o texto como modelo de língua.')]),
 text('MÉTODO','Como o TOEFL cobra leitura e escuta',[S('Formatos de tarefa','No formato atual do TOEFL iBT aparecem tarefas como “Complete the Words” (palavras incompletas em um texto), “Read in Daily Life” (avisos, e-mails, anúncios), “Read an Academic Passage”, “Listen and Choose a Response”, conversas, anúncios e palestras acadêmicas.',['Treine palavras incompletas em textos curtos desde cedo.','Leia avisos e mensagens reais: placas, e-mails, recibos.','Em escuta, treine tomar notas de palavras-chave, números e conectores (but, so, however).']),S('Atenção','Confirme sempre os formatos no site da ETS: eles mudam.')]),
 teach('Na prática: aula de leitura em 12 minutos','Planejar uma leitura curta com pré, durante e pós.',[('Pré (3 min)','Mostre o título e peça 3 palavras que o aluno espera ler. Pré-ensine 2 palavras.'),('Durante 1 (2 min)','Leitura silenciosa pela ideia geral: “quem, onde, o quê?”.'),('Durante 2 (4 min)','Perguntas de detalhe com evidência: o aluno sublinha onde achou.'),('Pós (3 min)','Resumo em uma frase e uma pergunta pessoal.')],['Ler em voz alta para toda a turma como única atividade.','Perguntas que se respondem sem ler (por conhecimento geral).'],'Turma mais rápida: textos mais longos e perguntas de inferência. Turma de apoio: leitura em coro e glossário.',['Onde no texto você achou isso?','O que o autor quer que o leitor faça?']),
 text('ARMADILHAS','Erros comuns',[S('Evite','',['Traduzir o texto inteiro antes de ler.','Tirar toda a dificuldade: o texto deve ter uns 5% de palavras novas.','Escuta sem tarefa: o aluno só “ouve” e não sabe o que buscar.','Usar só áudio de estúdio, lento e artificial: inclua variação de velocidade e sotaque.'])]),
 toefl([dict(type='complete',name='Complete the Words',items=[dict(text='The libr___ is open until mid___ on weekdays.',answers=['library','midnight'])]),dict(type='cloze',name='Read in Daily Life',items=[dict(q='Notice: “Quiet floors: 3 and 4. Student ID required after 10 p.m.” What do you need after 10 p.m.?',opts=['A student ID','A ticket','A phone'],ans=0,why='O aviso pede o documento de estudante.')])]),
 wrap('Ensine em 60 segundos: explique skimming e scanning a um colega com um exemplo de cada.','Escolha um texto curto de 80 palavras e escreva a tarefa de pré, de durante (duas passadas) e de pós.')]))
# ---------------------------------------------------------------- 5
L.append(('Ensinar fala, pronúncia e escrita','Fluência e precisão, pronúncia inteligível e como avaliar com rubricas.',[
 can('Planejar atividades que levam o aluno a falar e escrever com clareza.',['Equilibrar fluência e precisão.','Priorizar o que afeta a inteligibilidade.','Usar uma rubrica simples para falar e escrever.'],'Falar bem é ser entendido. Perfeição de sotaque não é meta.'),
 text('CONCEITO','Fluência × precisão',[S('Dois objetivos diferentes','Atividades de **precisão** controlam a língua (drills, completar). Atividades de **fluência** liberam a fala (conversar, contar, decidir) e toleram erros.',['Alterne os dois na mesma aula.','Em fluência, anote os erros e trate depois.','Dê tempo de planejamento: 1 minuto aumenta muito a qualidade da fala.'])]),
 text('CONCEITO','Pronúncia: o que priorizar',[S('Inteligibilidade','Foque no que mais atrapalha a compreensão de falantes de qualquer origem.',['**Sílaba forte da palavra** (de-GREE, não DE-gree).','**Sons que mudam o sentido** (ship × sheep, live × leave).','**Sílabas finais** e grupos de consoantes.','**Ritmo e ênfase na frase**: palavras de conteúdo mais fortes.']),S('Sons difíceis para brasileiros','/θ/ e /ð/ (th), o “r” inicial, a vogal no final de palavras (inserção de “i”), o -ed.')]),
 cards('TÉCNICAS','Cinco técnicas de prática',[('Shadowing','Repetir junto com o áudio, com 1 a 2 palavras de atraso.','Diálogo de 30 segundos.'),('Pares mínimos','Distinguir sons que mudam a palavra.','ship × sheep'),('Batida de sílaba forte','Bater na mesa na sílaba forte.','pro-FES-sor'),('Eco de frase','Repetir a frase com o mesmo ritmo e entonação.','“Could you help me?”'),('Gravar e ouvir','O aluno grava, ouve e anota um ponto a melhorar.','Resposta de 30 segundos.')]),
 quiz('Verifique seu entendimento',[('Em uma atividade de fluência, o mais adequado é:',['Interromper em cada erro.','Deixar falar e tratar os erros depois.','Pedir tradução de cada frase.'],1,'Fluência pede continuidade de fala.'),('Qual aspecto da pronúncia mais afeta a inteligibilidade?',['Imitar um sotaque específico.','A sílaba forte e os sons que mudam o sentido.','Falar muito rápido.'],1,'A inteligibilidade depende do acento e dos sons distintivos.'),('Shadowing é:',['Escrever o que ouviu.','Repetir junto com o áudio, quase ao mesmo tempo.','Traduzir o áudio.'],1,'É repetir em quase simultâneo, copiando ritmo e entonação.')]),
 text('MÉTODO','Rubrica simples para falar e escrever',[S('Quatro critérios, quatro níveis (1 a 4)','',['**Tarefa**: cumpriu o que foi pedido?','**Organização**: tem começo, razão e exemplo?','**Língua**: vocabulário e gramática adequados ao nível?','**Clareza**: dá para entender sem esforço (pronúncia ou ortografia)?']),S('No TOEFL','As respostas de fala e escrita são avaliadas por critérios parecidos (desenvolvimento, uso da língua, clareza). Treine respostas de 30 a 45 segundos e parágrafos curtos bem organizados.')]),
 teach('Na prática: resposta de fala em 10 minutos','Treinar uma resposta de 30 segundos com estrutura de “resposta, razão, exemplo”.',[('Pergunta (1 min)','“Do you prefer studying alone or with friends?”'),('Planejar (2 min)','Anote 3 palavras: a resposta, uma razão, um exemplo.'),('Falar (2 min)','Resposta de 30 segundos para o colega, que marca a rubrica.'),('Refinar (5 min)','Segunda versão com 1 melhora: um conectivo (because, for example).')],['Pedir respostas longas sem tempo de planejamento.','Corrigir pronúncia de palavra a palavra durante a fala.'],'Alunos tímidos: peça primeiro a gravação para ouvir, depois a fala ao vivo.',['Qual é a sua resposta em uma frase?','Que exemplo mostra isso?']),
 text('ARMADILHAS','Erros comuns',[S('Evite','',['Só corrigir gramática e ignorar a organização da resposta.','Pedir escrita sem modelo: mostre um bom texto de 40 a 60 palavras.','Ignorar o tempo: respostas de TOEFL têm limites, e o aluno precisa treinar com cronômetro.','Dar nota sem rubrica: o aluno não sabe o que melhorar.'])]),
 toefl([dict(type='interview',name='Take an Interview',prompts=['Tell me about a place you like to visit in your city.','What do you usually do on weekends?']),dict(type='build',name='Build a Sentence',items=[dict(words=['I','because','prefer','it','studying','alone','is','quiet'],answer='I prefer studying alone because it is quiet.',pt='Prefiro estudar sozinho porque é silencioso.')])]),
 wrap('Ensine em 60 segundos: ensine “resposta, razão, exemplo” a um colega com uma pergunta do dia a dia.','Grave uma resposta de 40 segundos e avalie-a com a rubrica de quatro critérios.')]))
# ---------------------------------------------------------------- 6
L.append(('Avaliar e preparar para o TOEFL','Avaliação formativa, rubricas, estratégias de prova e plano de estudo.',[
 can('Acompanhar o progresso do aluno e prepará-lo para o TOEFL com ética e método.',['Distinguir avaliação formativa e somativa.','Montar um plano de estudo de 12 semanas.','Orientar estratégias sem prometer nota.'],'O TOEFL é uma prova de inglês acadêmico, com formato e pontuação definidos pela ETS. Confirme sempre as regras vigentes.'),
 text('CONCEITO','Avaliar para ensinar',[S('Três usos da avaliação','',['**Diagnóstica**: onde o aluno está agora.','**Formativa**: durante o curso, para ajustar o ensino (bilhetes de saída, perguntas, rubricas).','**Somativa**: ao final de um período, para dizer se a meta foi atingida.']),S('Evidências variadas','Combine fala, escrita, compreensão e uso da língua. Uma única prova mostra pouco.')]),
 text('CONCEITO','TOEFL: o que é e para que serve',[S('Uma visão geral','O TOEFL iBT avalia inglês em contexto acadêmico: leitura, escuta, fala e escrita. Universidades e programas o usam como requisito de admissão. A ETS publica a correspondência entre pontuação e níveis do QECR.',['Não é um teste de “inglês de viagem”: o vocabulário e os textos são acadêmicos e do campus.','Existem formatos e escala de pontuação atualizados: consulte o guia oficial da ETS.','Preparar é desenvolver as habilidades, não decorar respostas.'])]),
 cards('TAREFAS','Tarefas que aparecem no preparo',[('Complete the Words','Completar palavras incompletas em um texto curto.','Treina leitura rápida e ortografia.'),('Listen and Choose a Response','Escolher a resposta adequada a uma fala.','Treina compreensão e pragmática.'),('Build a Sentence','Montar uma frase com as palavras dadas.','Treina ordem das palavras.'),('Listen and Repeat','Repetir frases de tamanho crescente.','Treina memória de curto prazo e ritmo.'),('Take an Interview','Responder perguntas em tempo limitado.','Treina organização de ideias ao falar.'),('Write for an Academic Discussion','Contribuir para uma discussão com um parágrafo.','Treina argumentação escrita.')]),
 quiz('Verifique seu entendimento',[('Qual avaliação ajuda o professor a ajustar a aula?',['Somativa','Formativa','Nenhuma'],1,'A avaliação formativa acontece durante o curso e orienta o ensino.'),('Sobre pontuação no TOEFL, o professor deve:',['Garantir uma nota.','Orientar estratégias e indicar o guia oficial da ETS.','Ensinar respostas decoradas.'],1,'Não se promete nota; confira sempre as regras vigentes.'),('Qual é o foco do TOEFL?',['Inglês de viagem.','Inglês em contexto acadêmico.','Inglês técnico de TI.'],1,'O foco é o inglês usado em ambientes acadêmicos.')]),
 text('MÉTODO','Plano de estudo de 12 semanas',[S('Estrutura','',['**Semanas 1–2**: diagnóstico e meta realista (nível de entrada e nível desejado).','**Semanas 3–8**: ciclos semanais com 1 habilidade em foco, vocabulário acadêmico e revisão espaçada.','**Semanas 9–11**: tarefas no formato do exame com tempo marcado e rubrica.','**Semana 12**: revisão dos erros mais frequentes e descanso antes da prova.']),S('Carga','Três a cinco sessões curtas por semana rendem mais do que uma sessão longa.')]),
 teach('Na prática: bilhete de saída formativo','Criar um bilhete de saída de 3 minutos que mostre o que a turma aprendeu.',[('Uma pergunta (1 min)','Escreva no quadro: “Diga em inglês como você pediria o preço de algo.”'),('Resposta (1 min)','Cada aluno escreve no papel, sem nome.'),('Triagem (1 min)','Você separa em três pilhas: certo, quase, errado.'),('Ajuste','Na aula seguinte, retome o ponto das pilhas “quase” e “errado”.')],['Aplicar prova sem devolutiva.','Dar só nota numérica, sem dizer o que melhorar.'],'Para turmas grandes, use perguntas de múltipla escolha com cartões coloridos.',['O que a turma ainda não consegue fazer?','Qual ajuste você fará na próxima aula?']),
 text('ÉTICA','Cuidados ao preparar para o exame',[S('Boas práticas','',['Não prometa nota nem prazo para resultado.','Use materiais oficiais e atualizados da ETS e identifique o que é simulado seu.','Respeite as regras da prova: nada de ensinar a burlar regras.','Cuide do bem-estar: o aluno ansioso rende menos.'])]),
 toefl([dict(type='cloze',name='Vocabulary in context',items=[dict(q='A short quiz at the end of class is a kind of _____ assessment.',opts=['formative','weekend','heavy'],ans=0,why='Quiz durante o curso para ajustar o ensino é avaliação formativa.'),dict(q='Before the exam, students should read the official _____ from ETS.',opts=['guide','kitchen','garden'],ans=0,why='“Guide” (guia) é o material oficial.')]),dict(type='build',name='Build a Sentence',items=[dict(words=['we','the','review','mistakes','will','next','week'],answer='We will review the mistakes next week.',pt='Vamos revisar os erros na semana que vem.')])]),
 wrap('Ensine em 60 segundos: explique a um colega a diferença entre avaliação formativa e somativa com um exemplo seu.','Monte um plano de estudo de 12 semanas para um aluno B1 que quer chegar ao B2, com uma habilidade em foco por semana.')]))

idx=[]
for i,(title,pt,frames) in enumerate(L,1):
    assert len(frames)==10,(i,len(frames))
    d=dict(id='fund-%02d'%i,n=i,part='F',name='Fundamentos',title=title,pt=pt,level='Fundamentos',frames=frames,unit=dict(n=0,name='Fundamentos de didática'))
    json.dump(d,open(OUT+'/%02d.json'%i,'w'),ensure_ascii=False,separators=(',',':'))
    idx.append(dict(id=d['id'],n=i,part='F',name='Fundamentos',title=title,pt=pt,unit=d['unit'],level='Fundamentos',minutes=20))
json.dump({'track':'fund','lessons':idx},open(R+'/data/formacao/index-fund.json','w'),ensure_ascii=False,separators=(',',':'))
print('fundamentos:',len(idx),'lições')
